struct node {
    int ID;             // ID of the process node
    int AT;             // Arrival Time of the process node
    int BT;             // Burst Time of the process node
    int priority;       // Priority of the process node
    int CT;             // Completion Time of the process node
    int WT;             // Waiting Time of the process node
    int TAT;            // Turn Around Time of the process node
    struct node *next;  // pointer to the node
};

// ========== Created - Assertion Operations ==========

// Asserts that two process queues have identical process data (ID, CT, WT, TAT) in the same order.
void assert_process_queue_equal(struct node *actual, struct node *expected) {
    struct node *actual_ptr = actual;
    struct node *expected_ptr = expected;

    while (actual_ptr != NULL && expected_ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(expected_ptr->ID, actual_ptr->ID);
        TEST_ASSERT_EQUAL_INT(expected_ptr->CT, actual_ptr->CT);
        TEST_ASSERT_EQUAL_INT(expected_ptr->WT, actual_ptr->WT);
        TEST_ASSERT_EQUAL_INT(expected_ptr->TAT, actual_ptr->TAT);
        actual_ptr = actual_ptr->next;
        expected_ptr = expected_ptr->next;
    }
    TEST_ASSERT_NULL(actual_ptr);
    TEST_ASSERT_NULL(expected_ptr);

    // Don't free expected list - it's managed by caller
}

// Asserts that the average CT, TAT, and WT calculated for a process queue match expected values within a small tolerance.
void assert_process_times_correct(struct node **root, float expected_avgCT, float expected_avgTAT, float expected_avgWT) {
    float tolerance = 0.001f;
    float actual_avgCT = 0.0f;
    float actual_avgTAT = 0.0f;
    float actual_avgWT = 0.0f;
    // Calculate actual averages
    struct node *ptr = *root;
    int count = 0;
    while (ptr != NULL) {
        actual_avgCT += ptr->CT;
        actual_avgTAT += ptr->TAT;
        actual_avgWT += ptr->WT;
        count++;
        ptr = ptr->next;
    }
    if (count > 0) {
        actual_avgCT /= count;
        actual_avgTAT /= count;
        actual_avgWT /= count;
    }
    TEST_ASSERT_FLOAT_WITHIN(tolerance, expected_avgCT, actual_avgCT);
    TEST_ASSERT_FLOAT_WITHIN(tolerance, expected_avgTAT, actual_avgTAT);
    TEST_ASSERT_FLOAT_WITHIN(tolerance, expected_avgWT, actual_avgWT);
}

// ========== Created - Utility Operations ==========

// Builds a process queue from arrays of process data (ID).
struct node* helper_build_process_queue(int *ids, int *ats, int *bts, int *priorities, int size) {
    struct node *root = NULL;
    for (int i = 0; i < size; i++) {
        // Simulate insert by creating nodes manually
        struct node *new_node = (struct node*)malloc(sizeof(struct node));
        new_node->ID = ids[i];
        new_node->AT = ats[i];
        new_node->BT = bts[i];
        new_node->priority = priorities[i];
        new_node->CT = 0;
        new_node->WT = 0;
        new_node->TAT = 0;
        new_node->next = NULL;

        if (root == NULL) {
            root = new_node;
        } else {
            struct node *ptr = root;
            while (ptr->next != NULL) {
                ptr = ptr->next;
            }
            ptr->next = new_node;
        }
    }
    return root;
}

// Frees all nodes in a process queue.
void helper_cleanup_process_queue(struct node **root) {
    if (root == NULL) {
        return;
    }
    struct node *current = *root;
    struct node *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *root = NULL;
}


